+    circ: &mut Circuit,
+    phase1: &QReg,
+    phase2: &QReg,
+    sign: &QReg,
+    work1: &[QReg],
+    work2: &[QReg],
+    physical_work_width: usize,
+    l_t: &[QReg],
+    l_t_prime: &[QReg],
+    l_s: &[QReg],
+    l_r_prime: &[QReg],
+    enable: &QReg,
+    above_guard: &QReg,
+    add_only: &QReg,
+    chain: &[QReg],
+    inverse: bool,
+    q828_entry_parity: Option<bool>,
+    uls_clean_lender: Option<&QReg>,
+    relocation_l_q: Option<&[QReg]>,
+) {
+    assert_eq!(work1.len(), work2.len());
+    assert!(!work1.is_empty());
+    assert_eq!(l_t.len(), l_s.len());
+    assert_l_r_prime_metadata_width(l_t.len(), l_r_prime.len());
+    let dirty_fused_tmp = q824_coefficient_dirty_fused_tmp_requested();
+    let dirty_keep_tmp = dirty_fused_tmp && chain.len() == 2;
+    assert_eq!(
+        chain.len(),
+        if dirty_fused_tmp && !dirty_keep_tmp {
+            1
+        } else {
+            2
+        }
+    );
+    assert!(
+        !dirty_fused_tmp
+            || !q824_coefficient_lq_high_host_requested()
